import { cnMerge, createTV } from 'tailwind-variants';
import { twMergeConfig } from '@/lib/tw-merge-config';

/**
 * 8341-ui のテーマ名を登録した tv。コンポーネントは必ずこちらを使う。
 * （tailwind-variants の tv をそのまま使うと `text-fg text-body-md` の文字色が消える）
 */
export const tv = createTV({ twMerge: true, twMergeConfig });

/** クラス名を結合し、競合するユーティリティは後勝ちで 1 つにする */
export const cn = (...classes: Parameters<typeof cnMerge>) => cnMerge(...classes)({ twMerge: true, twMergeConfig });

export type { VariantProps } from 'tailwind-variants';

/* このファイルは packages/tokens/scripts/generate-tw-merge.ts が生成します。直接編集しないでください。 */
/**
 * tailwind-variants のクラス統合に登録する 8341-ui 独自のテーマ名。
 * これが無いと `text-fg text-body-md` の文字色が消えるなど、クラスの競合判定を誤る。
 */
export const twMergeConfig = {
  extend: {
    theme: {
      text: ['display-lg', 'display-md', 'heading-xl', 'heading-lg', 'heading-md', 'heading-sm', 'heading-xs', 'heading-xxs', 'body-lg', 'body-md', 'body-sm', 'dense-md', 'dense-sm', 'label-md', 'label-sm', 'mono-md', 'mono-sm'],
      shadow: ['1', '2', '3'],
      spacing: ['inset-xs', 'inset-sm', 'inset-md', 'inset-lg', 'inset-xl', 'gap-xs', 'gap-sm', 'gap-md', 'stack-sm', 'stack-md', 'stack-lg', 'gutter', 'page-inline', 'control-sm', 'control-md', 'control-lg', 'target-min', 'icon-sm', 'icon-md', 'icon-lg'],
      container: ['content', 'prose'],
      radius: ['none', 'xs', 'sm', 'md', 'lg', 'xl', 'full'],
      'font-weight': ['regular', 'bold'],
    },
  },
} as const;

/**
 * フォーカス表示（二重リング: 内側が黄 color.focus.ring、外側が color.focus.outline）。
 * Base UI は data-focus-visible を付けないため、:focus-visible で描く。
 * 実体は styles/theme.css の @utility focus-ring。
 */
export const focusRing = 'focus-ring';
/** 子孫にフォーカスがあるとき自分にリングを描く（カード全体をリンクにする場合など） */
export const focusRingWithin = 'focus-ring-within';
